from functools import lru_cache

@lru_cache(None)
def f(maxi, no):
    if maxi < 10:
        return maxi - (0 < no <= maxi)
    q = maxi // 10
    r = maxi % 10
    ans = 0
    for x in range(10):
        if x == no:
            continue
        if x <= r:
            ans += f(q, x) + (x != 0)
        else:
            ans += f(q - 1, x) + (x != 0)
    return ans

